ALTER TABLE public.crm_customers ADD COLUMN custom_values jsonb NOT NULL DEFAULT '{}';
COMMENT ON COLUMN public.crm_customers.details IS 'DEPRECATED for new configurable fields: retained legacy text; use custom_values keyed by catalog field ID.';
CREATE TABLE public.crm_catalog_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),catalog_id uuid NOT NULL REFERENCES public.crm_catalogs(id),snapshot jsonb NOT NULL,recorded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.crm_catalog_versions TO authenticated; GRANT ALL ON public.crm_catalog_versions TO service_role;
ALTER TABLE public.crm_catalog_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY crm_versions_read ON public.crm_catalog_versions FOR SELECT TO authenticated USING(public.crm_can(auth.uid(),'biz.crm_use'));
CREATE INDEX crm_versions_lookup ON public.crm_catalog_versions(catalog_id,recorded_at DESC);
INSERT INTO public.crm_catalog_versions(catalog_id,snapshot,recorded_at) SELECT id,to_jsonb(c),created_at FROM public.crm_catalogs c;
CREATE OR REPLACE FUNCTION private.crm_scope_matches(cfg jsonb,g uuid,s uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT g IS NOT NULL AND CASE WHEN cfg->>'scope_mode'='shared' THEN true WHEN cfg->>'scope_mode'='segments' THEN EXISTS(WITH RECURSIVE ancestors AS (SELECT id,parent_id FROM crm_catalogs WHERE id=s UNION ALL SELECT c.id,c.parent_id FROM crm_catalogs c JOIN ancestors a ON c.id=a.parent_id) SELECT 1 FROM ancestors WHERE coalesce(cfg->'segment_ids','[]') ? id::text) WHEN cfg->>'scope_mode'='groups' OR (cfg->>'scope_mode' IS NULL AND jsonb_typeof(cfg->'group_ids')='array' AND jsonb_array_length(cfg->'group_ids')>0) THEN coalesce(cfg->'group_ids','[]') ? g::text ELSE false END $$;
CREATE OR REPLACE FUNCTION private.crm_field_value_ok(cfg jsonb,v jsonb,old_v jsonb DEFAULT NULL) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE typ text:=cfg->>'field_type'; item jsonb; x text; BEGIN IF v IS NULL OR v='null'::jsonb OR v='""'::jsonb OR v='[]'::jsonb THEN RETURN true; END IF; IF typ IN ('text','textarea','url','date','select') AND jsonb_typeof(v)<>'string' THEN RETURN false; END IF; IF typ IN ('text','textarea') THEN RETURN length(v#>>'{}')<=CASE WHEN typ='text' THEN 1000 ELSE 10000 END; ELSIF typ='url' THEN RETURN (v#>>'{}')~'^https?://[^[:space:]]+$' AND length(v#>>'{}')<=2048; ELSIF typ='date' THEN IF (v#>>'{}')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RETURN false; END IF; RETURN to_char((v#>>'{}')::date,'YYYY-MM-DD')=v#>>'{}'; ELSIF typ IN ('number','money') THEN RETURN jsonb_typeof(v)='number'; ELSIF typ='boolean' THEN RETURN jsonb_typeof(v)='boolean'; ELSIF typ IN ('select','multiselect') THEN IF typ='multiselect' AND jsonb_typeof(v)<>'array' THEN RETURN false; END IF; FOR item IN SELECT value FROM jsonb_array_elements(CASE WHEN typ='select' THEN jsonb_build_array(v) ELSE v END) LOOP IF jsonb_typeof(item)<>'string' THEN RETURN false; END IF; x:=item#>>'{}'; IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(cfg->'options','[]')) o WHERE o->>'id'=x AND (coalesce((o->>'active')::boolean,true) OR old_v=item OR coalesce(old_v,'[]') ? x)) THEN RETURN false; END IF; END LOOP; RETURN true; END IF; RETURN false; EXCEPTION WHEN OTHERS THEN RETURN false; END $$;
CREATE OR REPLACE FUNCTION private.crm_dynamic_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c crm_catalogs; pair record; oldv jsonb; mode text; opt jsonb; BEGIN PERFORM pg_advisory_xact_lock(hashtext('crm_catalogs')); IF TG_TABLE_NAME='crm_catalogs' THEN
IF NEW.kind IN ('custom_field','trait','channel','cooperation','output','product','need','occasion') THEN mode:=NEW.config->>'scope_mode'; IF mode IS NULL AND TG_OP='UPDATE' AND NEW.config=OLD.config THEN RETURN NEW; END IF; IF mode IS NULL AND coalesce(jsonb_array_length(NEW.config->'group_ids'),0)>0 THEN NEW.config:=NEW.config||'{"scope_mode":"groups"}'::jsonb; mode:='groups'; END IF; IF mode IS NULL OR mode<>ALL(ARRAY['shared','groups','segments']) THEN RAISE EXCEPTION 'Vui lòng xác định phạm vi áp dụng.'; END IF; IF mode='groups' AND (coalesce(jsonb_typeof(NEW.config->'group_ids'),'')<>'array' OR jsonb_array_length(NEW.config->'group_ids')=0) THEN RAISE EXCEPTION 'Vui lòng chọn nhóm áp dụng.'; END IF; IF mode='segments' THEN IF coalesce(jsonb_typeof(NEW.config->'segment_ids'),'')<>'array' OR jsonb_array_length(NEW.config->'segment_ids')=0 THEN RAISE EXCEPTION 'Vui lòng chọn tệp áp dụng.'; END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(NEW.config->'segment_ids') x WHERE NOT EXISTS(SELECT 1 FROM crm_catalogs WHERE id=x::uuid AND kind IN ('segment','block'))) THEN RAISE EXCEPTION 'Tệp áp dụng không hợp lệ.'; END IF; END IF;
END IF;
IF NEW.kind='custom_field' THEN IF NEW.parent_id IS NOT NULL OR coalesce(NEW.config->>'field_type','')<>ALL(ARRAY['text','textarea','number','money','date','boolean','select','multiselect','url']) THEN RAISE EXCEPTION 'Kiểu trường không hợp lệ.'; END IF; IF TG_OP='UPDATE' AND NEW.config->>'field_type' IS DISTINCT FROM OLD.config->>'field_type' AND (EXISTS(SELECT 1 FROM crm_customers WHERE custom_values ? OLD.id::text) OR EXISTS(SELECT 1 FROM crm_events WHERE before_data->'custom_values' ? OLD.id::text OR after_data->'custom_values' ? OLD.id::text)) THEN RAISE EXCEPTION 'Trường đã có dữ liệu; không thể đổi kiểu.'; END IF; IF NEW.config->>'field_type' IN ('select','multiselect') THEN IF jsonb_typeof(NEW.config->'options') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.config->'options')=0 THEN RAISE EXCEPTION 'Vui lòng thêm lựa chọn.'; END IF; FOR opt IN SELECT value FROM jsonb_array_elements(NEW.config->'options') LOOP IF nullif(opt->>'id','') IS NULL OR trim(coalesce(opt->>'name',''))='' THEN RAISE EXCEPTION 'Lựa chọn cần ID và tên ổn định.'; END IF; END LOOP; IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.config->'options') o GROUP BY o->>'id' HAVING count(*)>1) THEN RAISE EXCEPTION 'Lựa chọn bị trùng ID.'; END IF; IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(OLD.config->'options','[]')) o WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.config->'options') n WHERE n->>'id'=o->>'id')) THEN RAISE EXCEPTION 'Không xóa lựa chọn cũ; hãy ngừng sử dụng.'; END IF; END IF; END IF;
IF TG_OP='UPDATE' AND NEW.parent_id IS DISTINCT FROM OLD.parent_id AND EXISTS(WITH RECURSIVE subtree AS (SELECT OLD.id id UNION ALL SELECT c.id FROM crm_catalogs c JOIN subtree s ON c.parent_id=s.id) SELECT 1 FROM crm_customers x WHERE x.segment_id IN (SELECT id FROM subtree) OR x.group_id IN (SELECT id FROM subtree)) THEN RAISE EXCEPTION 'Nhánh danh mục đã có khách sử dụng; không thể đổi nhóm cha.'; END IF;
ELSE
IF jsonb_typeof(NEW.custom_values)<>'object' OR pg_column_size(NEW.custom_values)>131072 THEN RAISE EXCEPTION 'Thông tin chuyên sâu không hợp lệ.'; END IF;
IF TG_OP='UPDATE' THEN NEW.custom_values:=OLD.custom_values||NEW.custom_values; END IF;
FOR pair IN SELECT * FROM jsonb_each(NEW.custom_values) LOOP oldv:=NULL; IF TG_OP='UPDATE' THEN oldv:=OLD.custom_values->pair.key; END IF; IF oldv IS NOT DISTINCT FROM pair.value THEN CONTINUE; END IF; SELECT * INTO c FROM crm_catalogs WHERE id=pair.key::uuid AND kind='custom_field'; IF c.id IS NULL OR NOT c.active OR NOT private.crm_scope_matches(c.config,NEW.group_id,NEW.segment_id) THEN RAISE EXCEPTION 'Trường không thuộc phạm vi hoặc đã ngừng sử dụng.'; END IF; IF NOT private.crm_field_value_ok(c.config,pair.value,oldv) THEN RAISE EXCEPTION 'Giá trị không hợp lệ cho trường %.',c.name; END IF; END LOOP;
FOR c IN SELECT * FROM crm_catalogs WHERE kind='custom_field' AND active AND config->>'required'='true' LOOP IF private.crm_scope_matches(c.config,NEW.group_id,NEW.segment_id) AND (TG_OP='INSERT' OR NEW.custom_values IS DISTINCT FROM OLD.custom_values OR NEW.group_id IS DISTINCT FROM OLD.group_id OR NEW.segment_id IS DISTINCT FROM OLD.segment_id) AND (NEW.custom_values->c.id::text IS NULL OR NEW.custom_values->c.id::text IN ('null'::jsonb,'""'::jsonb,'[]'::jsonb)) THEN RAISE EXCEPTION 'Vui lòng nhập %.',c.name; END IF; END LOOP;
FOR c IN SELECT * FROM crm_catalogs WHERE id=ANY(NEW.related_ids) AND kind IN ('trait','channel','cooperation','output','product','need','occasion') LOOP IF (TG_OP='INSERT' OR NOT c.id=ANY(OLD.related_ids)) AND NOT private.crm_scope_matches(c.config,NEW.group_id,NEW.segment_id) THEN RAISE EXCEPTION 'Đặc điểm không thuộc phạm vi đã chọn.'; END IF; END LOOP;
END IF; RETURN NEW; END $$;
CREATE TRIGGER crm_dynamic_catalog BEFORE INSERT OR UPDATE ON public.crm_catalogs FOR EACH ROW EXECUTE FUNCTION private.crm_dynamic_guard();
CREATE TRIGGER crm_dynamic_customer BEFORE INSERT OR UPDATE ON public.crm_customers FOR EACH ROW EXECUTE FUNCTION private.crm_dynamic_guard();
CREATE OR REPLACE FUNCTION private.crm_catalog_snapshot() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO crm_catalog_versions(catalog_id,snapshot) VALUES(NEW.id,to_jsonb(NEW)); RETURN NEW; END $$;
CREATE TRIGGER crm_catalog_snapshot AFTER INSERT OR UPDATE ON public.crm_catalogs FOR EACH ROW EXECUTE FUNCTION private.crm_catalog_snapshot();
DO $$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.crm_catalog_save(jsonb)'::regprocedure) INTO d; IF position('''output''' in d)=0 THEN RAISE EXCEPTION 'Missing catalog extension point'; END IF; d:=replace(d,'''output''','''output'',''custom_field'''); EXECUTE d;
SELECT pg_get_functiondef('public.crm_customer_save(jsonb)'::regprocedure) INTO d; IF position('related_ids,details,note)' in d)=0 THEN RAISE EXCEPTION 'Missing customer insert extension point'; END IF; d:=replace(d,'related_ids,details,note)','related_ids,details,note,custom_values)'); d:=replace(d,'coalesce(_data->>''note'','''')) RETURNING','coalesce(_data->>''note'',''''),coalesce(_data->''custom_values'',''{}'')) RETURNING'); d:=replace(d,'revision=revision+1,updated_at=now() WHERE id=i','custom_values=coalesce(_data->''custom_values'',custom_values),revision=revision+1,updated_at=now() WHERE id=i'); EXECUTE d; END $$;
REVOKE ALL ON FUNCTION private.crm_scope_matches(jsonb,uuid,uuid),private.crm_field_value_ok(jsonb,jsonb,jsonb),private.crm_dynamic_guard(),private.crm_catalog_snapshot() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.crm_catalog_counts() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT crm_can(auth.uid(),'biz.crm_settings') THEN RAISE EXCEPTION 'Bạn không có quyền cài đặt CRM.'; END IF; RETURN (SELECT coalesce(jsonb_object_agg(id,n),'{}') FROM (SELECT cat.id,count(DISTINCT c.id) n FROM crm_catalogs cat LEFT JOIN crm_customers c ON (c.group_id=cat.id OR c.segment_id=cat.id OR cat.id=ANY(c.related_ids) OR c.custom_values ? cat.id::text) AND crm_owner_visible(c.owner_id) GROUP BY cat.id) q); END $$;